import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter: block obvious attack patterns in report names
    private static final Pattern REPORT_NAME_FILTER = Pattern.compile("^[a-zA-Z0-9_\\-]{1,64}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("list".equals(action)) {
            listReports(req, resp);
        } else if ("detail".equals(action)) {
            getReportDetail(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void listReports(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        // Category is validated against allowlist
        if (!isValidCategory(category)) {
            resp.sendError(400, "Invalid category");
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, created_at FROM reports WHERE category = ? AND tenant_id = ?");
            ps.setString(1, category);
            ps.setString(2, getTenantId(req));
            ResultSet rs = ps.executeQuery();
            JSONArray arr = new JSONArray();
            while (rs.next()) {
                JSONObject obj = new JSONObject();
                obj.put("id", rs.getInt("id"));
                obj.put("name", rs.getString("name"));
                obj.put("created_at", rs.getString("created_at"));
                arr.put(obj);
            }
            resp.setContentType("application/json");
            resp.getWriter().write(arr.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private void getReportDetail(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String reportId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Validate reportId is numeric
        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Build dynamic column selection - fields param allows selecting columns
        String columns = buildColumnList(fields);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Vulnerability: columns string is concatenated directly into SQL
            String sql = "SELECT " + columns + " FROM reports WHERE id = " + reportId 
                       + " AND tenant_id = '" + getTenantId(req) + "'";
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);
            JSONObject result = new JSONObject();
            if (rs.next()) {
                ResultSetMetaData meta = rs.getMetaData();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    result.put(meta.getColumnName(i), rs.getString(i));
                }
            }
            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());
        } catch (SQLException e) {
            // Return error detail for debugging (also leaks info)
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    private String buildColumnList(String fields) {
        if (fields == null || fields.isEmpty()) {
            return "id, name, category, content, created_at";
        }
        // Attempt to sanitize: remove semicolons and comments
        String sanitized = fields.replaceAll(";", "").replaceAll("--", "");
        // Split on comma, trim each, rejoin
        String[] parts = sanitized.split(",");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            String col = parts[i].trim();
            if (col.length() > 128) col = col.substring(0, 128);
            if (i > 0) sb.append(", ");
            sb.append(col);
        }
        return sb.toString();
    }

    private boolean isValidCategory(String cat) {
        if (cat == null) return false;
        return cat.matches("^(finance|operations|hr|engineering|sales)$");
    }

    private String getTenantId(HttpServletRequest req) {
        // Extracted from JWT by upstream gateway
        return (String) req.getAttribute("X-Tenant-ID");
    }
}
